  for (const f of fns) {
    if (f !== "step-start" && f !== "step-end" && f.indexOf("steps(") !== 0) return false;
  }
  return true;
}

function pagxParseColorChannels(value) {
  const m = (value || "").match(/rgba?\(([^)]+)\)/i);
  if (!m) return null;
  const parts = m[1].split(",").map((s) => parseFloat(s.trim()));
  if (parts.length < 3 || parts.slice(0, 3).some((x) => isNaN(x))) return null;
  const a = parts.length >= 4 && !isNaN(parts[3]) ? parts[3] : 1;
  return [parts[0], parts[1], parts[2], a];
}

function pagxParseFilterChannels(value) {
  const s = (value || "").trim();
  if (!s || s.toLowerCase() === "none") return { shadows: [], fblur: 0, fbrightness: 1 };
  const shadows = [];
  let fblur = 0;
  let fbrightness = 1;
  const parseAmount = (raw, defaultValue) => {
    const token = raw.trim();
    if (!token) return defaultValue;
    if (!/^[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?%?$/i.test(token)) return null;
    const parsed = parseFloat(token);
    if (!isFinite(parsed)) return null;
    return token.endsWith("%") ? parsed / 100 : parsed;
  };
  let i = 0;
  while (i < s.length) {
    while (i < s.length && /\s/.test(s[i])) i++;
    const open = s.indexOf("(", i);
    if (open < 0) break;
    const name = s.slice(i, open).trim().toLowerCase();
    let depth = 1;
    let j = open + 1;
    for (; j < s.length && depth > 0; j++) {
      if (s[j] === "(") depth++;
      else if (s[j] === ")") depth--;
    }
    const args = s.slice(open + 1, j - 1).trim();
    if (name === "drop-shadow") {
      const color = pagxParseColorChannels(args) || [0, 0, 0, 1];
      const rest = args.replace(/rgba?\([^)]*\)/i, " ");
      const nums = (rest.match(/-?[\d.]+/g) || []).map((n) => parseFloat(n));
      shadows.push({
        fdx: nums[0] || 0,
        fdy: nums[1] || 0,
        fdb: nums[2] || 0,
        fdr: color[0],
        fdg: color[1],
        fdbl: color[2],
        fda: color[3] != null ? color[3] : 1
      });
