      bw = cw;
      bh = ch;
    } else {
      const rect = el.getBoundingClientRect();
      bw = rect.width;
      bh = rect.height;
    }
  }
  if (!(bw > 0) || !(bh > 0)) return "";
  const num = (x) => String(Math.round(x * 1e3) / 1e3);
  const w = num(bw);
