function pagxResolveClipNoneSamples(el, samples) {
  let hasNone = false;
  let hasRect = false;
  for (const s of samples) {
    const cp = s["clip-path"];
    if (cp == null) continue;
    if (cp === "") {
      hasNone = true;
      continue;
    }
    const dm = cp.match(/path\(\s*(['"])((?:\\.|(?!\1).)*)\1\s*\)/i);
    const nums = dm && dm[2] ? dm[2].match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) : null;
