  if (!full) return;
  const fullPath = 'path("' + full + '")';
  for (const s of samples) {
    if (s["clip-path"] === "") s["clip-path"] = fullPath;
  }
}

function pagxStopScalarSeries(stops) {
  const series = {};
  const put = (key, i, v) => {
    if (!series[key]) series[key] = new Array(stops.length).fill(NaN);
    series[key][i] = v;
  };
