      const o = parseFloat(p["opacity"]);
      if (!isNaN(o)) put("opacity", i, o);
    }
    if (p["transform"] != null) {
      const mtx = pagxTransformToMatrix6(p["transform"]);
      if (mtx) {
        put("m0", i, mtx[0]);
        put("m1", i, mtx[1]);
        put("m2", i, mtx[2]);
        put("m3", i, mtx[3]);
        put("m4", i, mtx[4]);
        put("m5", i, mtx[5]);
      }
    }
    if (p["color"] != null) {
      const c = pagxParseColorChannels(p["color"]);
      if (c) {
        put("cr", i, c[0]);
        put("cg", i, c[1]);
        put("cb", i, c[2]);
        put("ca", i, c[3]);
      }
    }
    if (p["background-color"] != null) {
      const c = pagxParseColorChannels(p["background-color"]);
      if (c) {
        put("br", i, c[0]);
        put("bg", i, c[1]);
        put("bb", i, c[2]);
        put("ba", i, c[3]);
      }
    }
    if (p["fill"] != null) {
      const c = pagxParseColorChannels(p["fill"]);
      if (c) {
        put("flr", i, c[0]);
        put("flg", i, c[1]);
        put("flb", i, c[2]);
        put("fla", i, c[3]);
      }
    }
    if (p["stroke"] != null) {
      const c = pagxParseColorChannels(p["stroke"]);
      if (c) {
        put("skr", i, c[0]);
        put("skg", i, c[1]);
        put("skb", i, c[2]);
        put("ska", i, c[3]);
      }
    }
    if (p["stroke-dashoffset"] != null) {
      const v = parseFloat(p["stroke-dashoffset"]);
      if (!isNaN(v)) put("sdo", i, v);
    }
    const f = filterByStop[i];
    if (f) {
      for (let k = 0; k < maxShadowSlots; k++) {
        const sh = f.shadows[k];
        put("fd" + k + "x", i, sh ? sh.fdx : 0);
        put("fd" + k + "y", i, sh ? sh.fdy : 0);
        put("fd" + k + "b", i, sh ? sh.fdb : 0);
        put("fd" + k + "r", i, sh ? sh.fdr : 0);
        put("fd" + k + "g", i, sh ? sh.fdg : 0);
        put("fd" + k + "bl", i, sh ? sh.fdbl : 0);
        put("fd" + k + "a", i, sh ? sh.fda : 0);
      }
      put("fblur", i, f.fblur);
      put("fbrightness", i, f.fbrightness);
    }
    if (p["clip-path"] != null && p["clip-path"]) {
      const dm = p["clip-path"].match(/path\(\s*(['"])((?:\\.|(?!\1).)*)\1\s*\)/i);
      if (dm && dm[2]) {
        const nums = dm[2].match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi);
        if (nums) {
          for (let k = 0; k < nums.length; k++) {
            const val = parseFloat(nums[k]);
            if (!isNaN(val)) put("cp" + k, i, val);
          }
        }
      }
    }
  }
  return series;
}

function pagxRdpKeep(offsets, values, eps, absEps = 0) {
  const n = values.length;
  const keep = new Array(n).fill(false);
  if (n === 0) return keep;
  keep[0] = true;
  keep[n - 1] = true;
  if (n <= 2) return keep;
  let lo = Infinity;
  let hi = -Infinity;
  for (const v of values) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  const range = hi - lo;
  if (!(range > 0)) return keep;
  const effEps = absEps > 0 ? Math.min(eps, absEps / range) : eps;
  const norm = values.map((v) => (v - lo) / range);
  const stack = [[0, n - 1]];
  while (stack.length) {
    const seg = stack.pop();
    const a = seg[0];
    const b = seg[1];
    if (b <= a + 1) continue;
    const x1 = offsets[a];
    const y1 = norm[a];
    const dx = offsets[b] - x1;
    const dy = norm[b] - y1;
    const denom = Math.sqrt(dx * dx + dy * dy) || 1;
    let maxD = -1;
    let idx = -1;
    for (let i = a + 1; i < b; i++) {
      const d = Math.abs(dy * (offsets[i] - x1) - dx * (norm[i] - y1)) / denom;
      if (d > maxD) {
        maxD = d;
        idx = i;
      }
    }
    if (maxD > effEps && idx > a && idx < b) {
      keep[idx] = true;
      stack.push([a, idx]);
      stack.push([idx, b]);
    }
  }
  return keep;
}

function pagxDecimateStops(stops, eps = 0.01) {
  if (stops.length <= 2) return stops;
  const ABS_FLOOR_PX = 0.5;
  const offsets = stops.map((s) => s.offset);
  const series = pagxStopScalarSeries(stops);
  const keep = new Array(stops.length).fill(false);
  keep[0] = true;
  keep[stops.length - 1] = true;
  for (const key of Object.keys(series)) {
    const vals = series[key];
    const absEps = key === "m4" || key === "m5" || /^fd\d+[xyb]$/.test(key) || key === "fblur" || key[0] === "c" && key[1] === "p" ? ABS_FLOOR_PX : 0;
    let last = NaN;
    for (let i = 0; i < vals.length; i++) {
      if (isNaN(vals[i])) vals[i] = last;
      else last = vals[i];
    }
    let next = NaN;
    for (let i = vals.length - 1; i >= 0; i--) {
      if (isNaN(vals[i])) vals[i] = next;
      else next = vals[i];
    }
    const k = pagxRdpKeep(offsets, vals, eps, absEps);
    for (let i = 0; i < k.length; i++) {
      if (k[i]) keep[i] = true;
    }
  }
  const out = [];
  for (let i = 0; i < stops.length; i++) {
    if (keep[i]) out.push(stops[i]);
  }
  return out;
}

function pagxNormalizeTiming(t) {
  const v = (t || "").trim();
  if (!v) return "linear";
  return v;
}

function pagxSplitTopLevelCommas(value) {
  const out = [];
  let depth = 0;
  let start = 0;
